import ast
import importlib.util
import pathlib
import sys
import unittest
sys.path.insert(0, '/workspace')
from text_tools import slugify

class SlugAcceptance(unittest.TestCase):
    def test_basic_words(self):
        self.assertEqual(slugify('Hello World'), 'hello-world')
        self.assertEqual(slugify('already-slugged'), 'already-slugged')
    def test_punctuation_and_whitespace(self):
        self.assertEqual(slugify('  Hello,,,   WORLD!!  '), 'hello-world')
        self.assertEqual(slugify('one___two / three'), 'one-two-three')
    def test_unicode_normalization(self):
        self.assertEqual(slugify('Café Déjà Vu'), 'cafe-deja-vu')
    def test_empty_and_symbol_only(self):
        self.assertEqual(slugify(''), '')
        self.assertEqual(slugify(' !!! '), '')
    def test_non_strings(self):
        for value in (None, 1, [], {}, b'bytes'):
            with self.assertRaises(TypeError):
                slugify(value)
    def test_documentation_and_new_tests(self):
        root = pathlib.Path('/workspace')
        self.assertTrue((root / 'README.md').is_file())
        self.assertIn('slugify', (root / 'README.md').read_text())
        files = [p for p in root.rglob('test*.py') if p.name != 'test_baseline.py']
        self.assertTrue(files, 'Meaningful task tests are required and independently executed separately')
    def test_standard_library_only(self):
        tree = ast.parse(pathlib.Path('/workspace/text_tools.py').read_text())
        for node in ast.walk(tree):
            modules = [a.name.split('.')[0] for a in node.names] if isinstance(node, ast.Import) else [node.module.split('.')[0]] if isinstance(node, ast.ImportFrom) and node.module else []
            for name in modules:
                self.assertIn(name, sys.stdlib_module_names)

if __name__ == '__main__':
    unittest.main()
